create extension if not exists pgtap with schema extensions;
begin;
grant usage on schema extensions to authenticated,service_role;
select plan(30);
select ok(not has_function_privilege('anon','public.start_email_delivery(uuid,uuid)','EXECUTE'),'Anonymous cannot start SMTP delivery');
select ok(not has_table_privilege('anon','public.email_worker_health','SELECT'),'Worker diagnostics are private');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.email_outbox set next_attempt_at=now()+interval '1 day';
insert into public.email_outbox(id,template,recipient,dedupe_key,source_type)
values('ac000000-0000-4000-8000-000000000001','isolated_notification','qa@example.test','isolated-worker-fixture','operational');
create temporary table lease1 as select * from public.claim_email_outbox(null,1);
select is((select count(*) from lease1),1::bigint,'One worker claims the ready job');
select is((select attempts from lease1),1,'Claim records an attempt');
select ok((select lease_token from lease1) is not null,'Claim has a unique fencing token');
select is((select count(*) from public.claim_email_outbox(null,1)),0::bigint,'Another worker cannot claim the same job');
select is(public.start_email_delivery((select id from lease1),gen_random_uuid()),false,'Wrong token cannot start delivery');
select is(public.start_email_delivery((select id from lease1),(select lease_token from lease1)),true,'Current lease starts delivery');
select is(public.start_email_delivery((select id from lease1),(select lease_token from lease1)),false,'Sending cannot start twice');
select is(public.finish_email_delivery((select id from lease1),gen_random_uuid(),'accepted'),false,'Stale token cannot acknowledge another worker');
select is(public.finish_email_delivery((select id from lease1),(select lease_token from lease1),'retry','451 temporary refusal'),true,'Definite refusal schedules retry');
select ok((select status='failed' and next_attempt_at>now()+interval '50 seconds' from public.email_outbox where id=(select id from lease1)),'First retry backs off by one minute');
select is((select count(*) from public.claim_email_outbox(null,1)),0::bigint,'Backoff prevents an immediate retry');
update public.email_outbox set next_attempt_at=now() where id=(select id from lease1);
create temporary table lease2 as select * from public.claim_email_outbox(null,1);
select is((select attempts from lease2),2,'Retry increments attempts');
select public.start_email_delivery((select id from lease2),(select lease_token from lease2));
select public.finish_email_delivery((select id from lease2),(select lease_token from lease2),'ambiguous','Timeout after DATA');
select is((select status from public.email_outbox where id=(select id from lease2)),'needs_review','Uncertain SMTP acceptance is quarantined');
select is((select count(*) from public.claim_email_outbox(null,1)),0::bigint,'Uncertain messages are never automatically resent');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.resolve_email_delivery('ac000000-0000-4000-8000-000000000001','retry','Provider checked, not accepted',null)$$,'42501','Admin MFA required','AAL1 cannot reconcile delivery');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.resolve_email_delivery('ac000000-0000-4000-8000-000000000001','retry',null,null)$$,'P0001','Reconciliation note required','Reconciliation requires an audit note');
select throws_ok($$select public.resolve_email_delivery('ac000000-0000-4000-8000-000000000001','sent','Provider checked and found accepted',null)$$,'P0001','Provider evidence required','Marking accepted requires provider evidence');
select is(public.resolve_email_delivery('ac000000-0000-4000-8000-000000000001','retry','Provider records confirm no acceptance',null),true,'AAL2 can authorise a documented safe retry');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
create temporary table lease3 as select * from public.claim_email_outbox(null,1);
update public.email_outbox set locked_at=now()-interval '6 minutes' where id=(select id from lease3);
create temporary table reclaimed as select * from public.claim_email_outbox(null,1);
select is((select count(*) from reclaimed),1::bigint,'A worker lost before SMTP starts can be safely reclaimed');
select public.start_email_delivery((select id from reclaimed),(select lease_token from reclaimed));
update public.email_outbox set locked_at=now()-interval '6 minutes' where id=(select id from reclaimed);
select * from public.claim_email_outbox(null,1);
select is((select status from public.email_outbox where id=(select id from reclaimed)),'needs_review','A stale lease after sending starts requires reconciliation');
insert into public.email_outbox(id,template,recipient,dedupe_key,source_type)
values('ac000000-0000-4000-8000-000000000002','isolated_notification','qa@example.test','isolated-worker-accepted','operational');
create temporary table accepted_lease as select * from public.claim_email_outbox(null,1);
select public.start_email_delivery((select id from accepted_lease),(select lease_token from accepted_lease));
select ok(public.finish_email_delivery((select id from accepted_lease),(select lease_token from accepted_lease),'accepted',null,'provider-accepted','<isolated@example.test>'),'Provider acceptance is acknowledged');
select ok((select status='sent' and sent_at is not null and provider_message_id='provider-accepted' and smtp_message_id='<isolated@example.test>' from public.email_outbox where id=(select id from accepted_lease)),'Acceptance persists both provider identifiers and timestamp');
insert into public.email_outbox(id,template,recipient,dedupe_key,source_type,attempts)
values('ac000000-0000-4000-8000-000000000003','isolated_notification','qa@example.test','isolated-worker-exhausted','operational',4);
create temporary table final_lease as select * from public.claim_email_outbox(null,1);
select public.finish_email_delivery((select id from final_lease),(select lease_token from final_lease),'retry','451 final refusal');
select is((select status from public.email_outbox where id=(select id from final_lease)),'dead','Five definite failures stop automatic retries');
insert into public.contact_enquiries(id,name,email,subject,message,consent)
values('ac000000-0000-4000-8000-000000000004','Isolated QA','qa@example.test','Worker test','A disposable database assertion.',true);
select is((select count(*) from public.email_outbox where source_id='ac000000-0000-4000-8000-000000000004'),1::bigint,'Contact save atomically enqueues one notification');
delete from public.contact_enquiries where id='ac000000-0000-4000-8000-000000000004';
select is((select status from public.email_outbox where source_id='ac000000-0000-4000-8000-000000000004'),'cancelled','Removing an unsent enquiry cancels its notification');
update public.email_outbox set source_type='order' where id='ac000000-0000-4000-8000-000000000001';
select public.enqueue_notification_alert();
select public.enqueue_notification_alert();
select is((select count(*) from public.email_outbox where dedupe_key='notification-alert:'||to_char(now() at time zone 'UTC','YYYY-MM-DD')),1::bigint,'Persistent failures produce at most one consolidated alert per UTC day');
select ok(not has_function_privilege('anon','public.enqueue_notification_alert()','EXECUTE'),'Anonymous cannot generate operational alerts');
select ok(not has_function_privilege('authenticated','public.finish_email_delivery(uuid,uuid,text,text,text,text)','EXECUTE'),'Customers cannot forge provider acceptance');
select * from finish();
rollback;
